style.css:
/* Hide the original Robux balance */
span[title*="Robux Balance"], div[aria-label*="Robux balance"], [data-testid="nav-robux-balance"] {
    color: transparent !important;
    pointer-events: none;
    user-select: none;
    position: relative;
}

/* Insert "10M+" as the new balance */
span[title*="Robux Balance"]::after, div[aria-label*="Robux balance"]::after, [data-testid="nav-robux-balance"]::after {
    content: "10M+" !important;
    font-size: 16px !important;
    color: white !important;
    font-weight: bold;
    position: absolute;
    left: 0;
    top: 0;
    visibility: visible;
}
